SET SESSION sql_mode=@mock_original_sql_mode;

-- 다음 조회는 저장 데이터 검증이며 API 실행 결과가 아니다.
SELECT analysis_status, COUNT(*) AS article_count FROM articles GROUP BY analysis_status;
-- 예상: COMPLETED 17, DROPPED 1, FAILED 1, PROCESSING 1.
SELECT user_id, COUNT(*) AS unique_read_articles FROM article_reads GROUP BY user_id;
-- 예상: 950001=3, 950002=7. 신규 사용자 950003은 기록 없음.
SET @mock_asof='2024-05-25 05:45:00.000000';
SELECT recommendation_type, event_id, `rank`, available_at
FROM user_recommendations
WHERE user_id=950001 AND available_at=(
 SELECT MAX(available_at) FROM user_recommendations WHERE user_id=950001 AND available_at<=@mock_asof
) ORDER BY recommendation_type, `rank`;
-- 예상: 2024-05-24 18:00 회차 4건. @mock_asof를 2024-05-25 06:00으로 바꾸면 다음 회차 4건.
